package com.medibook.controller;
import com.medibook.dto.AppointmentDtos.*;import com.medibook.entity.*;import com.medibook.repository.UserRepository;import com.medibook.service.AppointmentService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/appointments") public class AppointmentController {private final AppointmentService service;private final UserRepository users;public AppointmentController(AppointmentService s,UserRepository users){service=s;this.users=users;}
 @PostMapping @PreAuthorize("hasRole('PATIENT')") public AppointmentView book(@AuthenticationPrincipal Long id,@Valid @RequestBody Booking body){return view(service.book(id,body));}
 @GetMapping("/me") @PreAuthorize("hasAnyRole('PATIENT','DOCTOR')") public List<AppointmentView> mine(@AuthenticationPrincipal Long id,Authentication auth){return service.mine(id,auth.getAuthorities().iterator().next().getAuthority()).stream().map(this::view).toList();}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('PATIENT','DOCTOR','ADMIN')") public AppointmentView get(@PathVariable long id,@AuthenticationPrincipal Long actor,Authentication auth){return view(service.get(id,actor,auth.getAuthorities().iterator().next().getAuthority()));}
 @PatchMapping("/{id}/cancel") @PreAuthorize("hasRole('PATIENT')") public AppointmentView cancel(@PathVariable long id,@AuthenticationPrincipal Long actor){return view(service.cancel(id,actor));}
 @PatchMapping("/{id}/reschedule") @PreAuthorize("hasRole('PATIENT')") public AppointmentView reschedule(@PathVariable long id,@AuthenticationPrincipal Long actor,@Valid @RequestBody Reschedule body){return view(service.reschedule(id,actor,body));}
 @PatchMapping("/{id}/status") @PreAuthorize("hasRole('DOCTOR')") public AppointmentView status(@PathVariable long id,@AuthenticationPrincipal Long actor,@Valid @RequestBody StatusChange body){return view(service.changeStatus(id,actor,body.status()));}
 private AppointmentView view(Appointment a){AppUser p=users.findById(a.getPatientId()).orElseThrow();AppUser d=users.findById(a.getDoctorId()).orElseThrow();return new AppointmentView(a.getId(),a.getPatientId(),p.getFullName(),a.getDoctorId(),d.getFullName(),a.getStartAt(),a.getEndAt(),a.getStatus().name(),a.getReason());}
}
